flowergift.body:
onWeatherChange(pokemon) {
      if (!pokemon.isActive || pokemon.baseSpecies.baseSpecies !== "Cherrim" || pokemon.transformed) return;
      if (!pokemon.hp) return;
      if (["sunnyday", "desolateland"].includes(pokemon.effectiveWeather())) {
        if (pokemon.species.id !== "cherrimsunshine") {
          pokemon.formeChange("Cherrim-Sunshine", this.effect, false, "0", "[msg]");
        }
      } else {
        if (pokemon.species.id === "cherrimsunshine") {
          pokemon.formeChange("Cherrim", this.effect, false, "0", "[msg]");
        }
      }
    }

forecast.body:
onWeatherChange(pokemon) {
      if (pokemon.baseSpecies.baseSpecies !== "Castform" || pokemon.transformed) return;
      let forme = null;
      switch (pokemon.effectiveWeather()) {
        case "sunnyday":
        case "desolateland":
          if (pokemon.species.id !== "castformsunny") forme = "Castform-Sunny";
          break;
        case "raindance":
        case "primordialsea":
          if (pokemon.species.id !== "castformrainy") forme = "Castform-Rainy";
          break;
        case "hail":
        case "snowscape":
          if (pokemon.species.id !== "castformsnowy") forme = "Castform-Snowy";
          break;
        default:
          if (pokemon.species.id !== "castform") forme = "Castform";
          break;
      }
      if (pokemon.isActive && forme) {
        pokemon.formeChange(forme, this.effect, false, "0", "[msg]");
      }
    }

harvest.body:
onResidual(pokemon) {
      if (this.field.isWeather(["sunnyday", "desolateland"]) || this.randomChance(1, 2)) {
        if (pokemon.hp && !pokemon.item && this.dex.items.get(pokemon.lastItem).isBerry) {
          pokemon.setItem(pokemon.lastItem);
          pokemon.lastItem = "";
          this.add("-item", pokemon, pokemon.getItem(), "[from] ability: Harvest");
        }
      }
    }

imposter.body:
onSwitchIn(pokemon) {
      const target = pokemon.side.foe.active[pokemon.side.foe.active.length - 1 - pokemon.position];
      if (target) {
        pokemon.transformInto(target, this.dex.abilities.get("imposter"));
      }
    }

magicbounce.body:
onTryHit(target, source, move) {
      if (target === source || move.hasBounced || !move.flags["reflectable"] || target.isSemiInvulnerable()) {
        return;
      }
      const newMove = this.dex.getActiveMove(move.id);
      newMove.hasBounced = true;
      newMove.pranksterBoosted = false;
      this.actions.useMove(newMove, target, { target: source });
      return null;
    }

onAllyTryHitSide(target, source, move) {
      if (target.isAlly(source) || move.hasBounced || !move.flags["reflectable"]) {
        return;
      }
      const newMove = this.dex.getActiveMove(move.id);
      newMove.hasBounced = true;
      newMove.pranksterBoosted = false;
      this.actions.useMove(newMove, this.effectState.target, { target: source });
      move.hasBounced = true;
      return null;
    }

mummy.body:
onDamagingHit(damage, target, source, move) {
      const sourceAbility = source.getAbility();
      if (sourceAbility.flags["cantsuppress"] || sourceAbility.id === "mummy") {
        return;
      }
      if (this.checkMoveMakesContact(move, source, target, !source.isAlly(target))) {
        source.setAbility("mummy", target);
      }
    }

stickyhold.body:
onTakeItem(item, pokemon, source) {
      if (!this.activeMove) throw new Error("Battle.activeMove is null");
      if (!pokemon.hp || pokemon.item === "stickybarb") return;
      if (source && source !== pokemon || this.activeMove.id === "knockoff") {
        this.add("-activate", pokemon, "ability: Sticky Hold");
        return false;
      }
    }

trace.body:
onUpdate(pokemon) {
      if (!this.effectState.seek) return;
      const possibleTargets = pokemon.adjacentFoes().filter(
        (target2) => !target2.getAbility().flags["notrace"] && target2.ability !== "noability"
      );
      if (!possibleTargets.length) return;
      const target = this.sample(possibleTargets);
      const ability = target.getAbility();
      pokemon.setAbility(ability, target);
    }

pursuit.body:
onFoeBeforeSwitchOut(pokemon) {
        const source = this.effectState.source;
        this.debug("Pursuit start");
        if (!source.isAdjacent(pokemon) || !source.hp || source.volatiles["encore"] && source.volatiles["encore"].move !== "pursuit" || !this.queue.cancelMove(source)) {
          return;
        }
        if (!pokemon.pursuitActivated) {
          this.add("-activate", pokemon, "move: Pursuit");
          pokemon.pursuitActivated = true;
        }
        if (source.canMegaEvo || source.canUltraBurst || source.canTerastallize) {
          for (const [actionIndex, action] of this.queue.entries()) {
            if (action.pokemon === source) {
              if (action.choice === "megaEvo") {
                this.actions.runMegaEvo(source);
              } else if (action.choice === "terastallize") {
                this.actions.terastallize(source);
              } else {
                continue;
              }
              this.queue.list.splice(actionIndex, 1);
              break;
            }
          }
        }
        pokemon.removeVolatile("destinybond");
        this.actions.runMove("pursuit", source, source.getLocOf(pokemon), { sourceEffect: this.effectState.sourceEffect });
      }

relicsong.body:
onAfterMoveSecondarySelf(pokemon) {
      if (pokemon.baseSpecies.baseSpecies === "Meloetta" && !pokemon.transformed) {
        const meloettaForme = pokemon.species.id === "meloettapirouette" ? "" : "-Pirouette";
        pokemon.formeChange("Meloetta" + meloettaForme, this.effect, false, "0", "[msg]");
